from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import Optional


class PromotionExpiredError(Exception):
    """Raised when an order references a promotion that has expired."""

    def __init__(self, code: str, expired_at: datetime):
        super().__init__(f"Promotion {code!r} expired at {expired_at.isoformat()}")
        self.code = code
        self.expired_at = expired_at


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime

    def is_expired(self, now: datetime) -> bool:
        return now >= self.expires_at


def checkout_total(subtotal: Decimal, promotion: Optional[Promotion], now: datetime) -> Decimal:
    """Total for an order.

    PROVISIONAL POLICY (product undecided): an expired promotion rejects the
    order. Silently dropping it would surprise the customer with a higher
    price, and rejecting lets the caller later offer a "confirm without
    promotion" step. Change only the expired branch to alter the policy.
    """
    if promotion is None:
        return subtotal
    if promotion.is_expired(now):
        raise PromotionExpiredError(promotion.code, promotion.expires_at)
    return (subtotal * (Decimal(100) - promotion.percent_off) / 100).quantize(Decimal("0.01"))
