import unittest
from datetime import datetime, timedelta
from decimal import Decimal

from checkout import Promotion, PromotionExpiredError, checkout_total

NOW = datetime(2026, 11, 22, 12, 0)


def promo(delta):
    return Promotion("SAVE10", Decimal(10), NOW + delta)


class CheckoutTests(unittest.TestCase):
    def test_no_promotion(self):
        self.assertEqual(checkout_total(Decimal("50.00"), None, NOW), Decimal("50.00"))

    def test_valid_promotion_applies(self):
        self.assertEqual(checkout_total(Decimal("50.00"), promo(timedelta(days=1)), NOW), Decimal("45.00"))

    # Provisional: product has not decided; see checkout_total docstring.
    def test_expired_promotion_rejects_order(self):
        with self.assertRaises(PromotionExpiredError) as cm:
            checkout_total(Decimal("50.00"), promo(-timedelta(days=1)), NOW)
        self.assertEqual(cm.exception.code, "SAVE10")

    def test_promotion_expiring_exactly_now_is_expired(self):
        with self.assertRaises(PromotionExpiredError):
            checkout_total(Decimal("50.00"), promo(timedelta(0)), NOW)


if __name__ == "__main__":
    unittest.main()
